INSERT INTO hollow_knight_itens (nome, regiao, tipo, descricao, imagem_url) VALUES
('Dirtmouth', 'Dirtmouth', 'Região', 'Dirtmouth é a pequena vila que fica logo acima do Poço, na entrada de Hallownest. No auge do reino, era uma cidade movimentada: ponto de partida e de chegada dos viajantes que seguiam para o interior por King''s Pass, a pé, de Stag ou pelo elevador mecânico que leva às minas de cristal.', 'estilos/áreas/Dirtmouth.png'),
('Howling Cliffs', 'Howling Cliffs', 'Região', 'Os Penhascos Uivantes são uma região pouco habitada no noroeste de Hallownest, onde o reino termina e começa um vasto ermo. Ventos constantes varrem o chão coberto de cascas e carcaças de insetos.', 'estilos/áreas/Howling_Cliffs.png'),
('Forgotten Crossroads', 'Forgotten Crossroads', 'Região', 'As Encruzilhadas Esquecidas são as cavernas logo abaixo de Dirtmouth, o primeiro grande território de Hallownest que o Cavaleiro explora. No auge do reino, eram o coração das viagens: uma vila movimentada, ligada por estradas a todas as outras regiões.', 'estilos/áreas/Forgotten_Crossroads.png'),
('Greenpath', 'Greenpath', 'Região', 'Greenpath é uma caverna exuberante a oeste das Encruzilhadas Esquecidas, de vales cobertos de musgo, vegetação densa e largos lagos de ácido. Seus habitantes são a Tribo Mosskin, insetos de aparência vegetal cujo musgo se confunde com o ambiente.', 'estilos/áreas/Greenpath.png'),
('Fog Canyon', 'Fog Canyon', 'Região', 'O Cânion da Névoa é uma região pequena e enevoada entre Greenpath e os Ermos Fúngicos. Sua geologia lembra a de Greenpath, o que sugere que os dois lugares já foram ligados. Uma guarnição dos Guardas do Reino chegou a manter um posto aqui.', 'estilos/áreas/Fog_Canyon.png'),
('Fungal Wastes', 'Fungal Wastes', 'Região', 'Os Ermos Fúngicos são uma região úmida perto do centro de Hallownest, ligada a várias outras áreas. Seus habitantes nativos são o Clã dos Cogumelos, de mente coletiva, e a Tribo Mantis.', 'estilos/áreas/Fungal_Wastes.png'),
('Queen''s Gardens', 'Queen''s Gardens', 'Região', 'Os Jardins da Rainha pertenceram a Unn e à Tribo Mosskin. Mais tarde, a White Lady anexou a área e a transformou em refúgio bem guardado. Ela se prendeu em sua câmara aqui e, quando a Infecção voltou, os jardins cresceram selvagens e sem controle.', 'estilos/áreas/Queen''s_Gardens.png'),
('Deepnest', 'Deepnest', 'Região', 'Deepnest, no sudoeste de Hallownest, era o lar da Tribo das Aranhas e dos Weavers, dois grupos inteligentes de aracnídeos. Ambos eram governados pela Rainha Herrah, a Fera, a partir da Distant Village, ao lado de um sire de casta honrada cuja identidade é desconhecida.', 'estilos/áreas/Deepnest.png'),
('Ancient Basin', 'Ancient Basin', 'Região', 'A Bacia Antiga é uma área desolada abaixo das Vias Fluviais Reais. Suas estruturas e estradas antigas parecem moldadas como se a própria rocha tivesse vontade.', 'estilos/áreas/Ancient_Basin.png'),
('City of Tears', 'City of Tears', 'Região', 'A Cidade das Lágrimas é a capital de Hallownest, no centro do reino, e seu nome original se perdeu. Fica numa caverna gigante abaixo do Blue Lake, e a água que goteja do teto provoca a chuva constante que dá nome ao lugar. Seu eixo principal era o Caminho do Peregrino.', 'estilos/áreas/City_of_Tears.png'),
('Royal Waterways', 'Royal Waterways', 'Região', 'As Vias Fluviais Reais são uma rede de canos de esgoto e estruturas de apoio abaixo da Cidade das Lágrimas, construídas para levar embora os resíduos da capital. A chuva constante de cima, com o tempo, lavou os canos e deixou-os limpos.', 'estilos/áreas/Royal_Waterways.png'),
('Crystal Peak', 'Crystal Peak', 'Região', 'O Pico Cristalino é uma grande montanha cintilante a leste de Dirtmouth, onde foram escavadas minas para extrair seus cristais. No auge de Hallownest, elas abasteciam as cidades do reino com um fluxo constante de cristal.', 'estilos/áreas/Crystal_Peak.png'),
('Resting Grounds', 'Resting Grounds', 'Região', 'Os Terrenos de Repouso são o cemitério de Hallownest, um lugar sagrado e silencioso. Aqui repousam os que partiram, e as lápides marcam o descanso de muitos habitantes do reino.', 'estilos/áreas/Resting_Grounds.png'),
('Kingdom''s Edge', 'Kingdom''s Edge', 'Região', 'A Orla do Reino é o limite leste de Hallownest, uma paisagem de penhascos, cinzas e areia que marca a fronteira entre o reino e o vazio além dele.', 'estilos/áreas/Kingdom''s_Edge.png'),
('The Hive', 'The Hive', 'Região', 'A Colmeia é habitada por guerreiros aéreos governados por uma rainha. Embora exista dentro de Hallownest, a colônia sempre ficou à parte dos assuntos do reino e isolada das terras do Rei Pálido.', 'estilos/áreas/The_Hive.png'),
('The Abyss', 'The Abyss', 'Região', 'O Abismo é a área mais baixa de Hallownest, abaixo da Bacia Antiga, e a origem do Vazio. Antes da fundação do reino, uma antiga civilização ligada ao Abismo adorava o Vazio. Quando o Rei Pálido o descobriu, estudou o Vazio ali.', 'estilos/áreas/The_Abyss.png'),
('Elderbug', 'Dirtmouth', 'NPC', 'O bondoso e nostálgico ancião de Dirtmouth, o único morador que nunca partiu. Recebe o Cavaleiro e conta a história da vila.', 'https://cdn.wikimg.net/en/hkwiki/images/4/40/Elderbug.png'),
('Sly', 'Dirtmouth', 'NPC', 'Comerciante astuto que volta à vila depois de ser resgatado. Atende na loja de Dirtmouth e, como Nailsage, mestre dos Nailmasters, concede a Nailmaster''s Glory.', 'https://cdn.wikimg.net/en/hkwiki/images/f/f9/Sly.png'),
('Iselda', 'Dirtmouth', 'NPC', 'Esposa de Cornifer. Abre uma loja de mapas ao lado da Estação do Stag depois que o Cavaleiro compra um mapa ou derrota o False Knight.', 'https://cdn.wikimg.net/en/hkwiki/images/5/50/Iselda.png'),
('Bretta', 'Dirtmouth', 'NPC', 'Moradora tímida que volta para casa depois de ser resgatada nos Ermos Fúngicos. Sua casa guarda um Fragmento de Máscara.', 'https://cdn.wikimg.net/en/hkwiki/images/9/96/Bretta.png'),
('Confessor Jiji', 'Dirtmouth', 'NPC', 'Mora na caverna a leste da vila, atrás da porta de pedra do cemitério, que só se abre com uma Simple Key.', 'https://cdn.wikimg.net/en/hkwiki/images/6/65/Confessor_Jiji.png'),
('Tiso', 'Dirtmouth', 'NPC', 'Aventureiro arrogante, encontrado ao lado do poço de Dirtmouth. Busca os desafios do Colosseum e despreza os fracos.', 'https://cdn.wikimg.net/en/hkwiki/images/b/b1/Tiso.png'),
('The Last Stag', 'Dirtmouth', 'NPC', 'O Stag que transporta o Cavaleiro entre as estações de Hallownest. Nasceu no Stag Nest, nos Penhascos Uivantes.', 'https://cdn.wikimg.net/en/hkwiki/images/a/af/Last_Stag.png'),
('Divine', 'Dirtmouth', 'NPC', 'Aparece na tenda menor da Trupe Grimm e troca os Fragile Charms de Leg Eater por versões Unbreakable em troca de Geo.', 'https://cdn.wikimg.net/en/hkwiki/images/f/f9/Divine.png'),
('Troupe Master Grimm', 'Dirtmouth', 'NPC', 'Líder da Trupe Grimm, no palco da tenda maior. Oferece o Grimmchild e é o centro da missão da Trupe.', 'https://cdn.wikimg.net/en/hkwiki/images/5/5b/B_Grimm.png'),
('Nailmaster Mato', 'Howling Cliffs', 'NPC', 'Um dos três discípulos do Grande Nailsage Sly. Vive em sua cabana e ensina a Nail Art Cyclone Slash.', 'https://cdn.wikimg.net/en/hkwiki/images/6/61/Mato.png'),
('Cornifer', 'Howling Cliffs', 'NPC', 'O cartógrafo viajante. Fica na encosta, ao lado da entrada da caverna que leva a Joni''s Repose, e vende o mapa da região.', 'https://cdn.wikimg.net/en/hkwiki/images/f/ff/Cornifer.png'),
('Mister Mushroom', 'Howling Cliffs', 'NPC', 'Arauto que visita sete regiões de Hallownest em ordem e fala como se falasse sozinho. Os Penhascos Uivantes são uma de suas paradas.', 'https://cdn.wikimg.net/en/hkwiki/images/f/fc/Mister_Mushroom.png'),
('Blue Child Joni', 'Howling Cliffs', 'Espírito', 'Espírito que repousa em Joni''s Repose, perto de um altar. É a origem do Joni''s Blessing.', 'https://cdn.wikimg.net/en/hkwiki/images/9/96/Joni.png'),
('Gorb', 'Howling Cliffs', 'Espírito', 'Criatura mística que dizia saber tudo e pedia que os outros reverenciassem a própria mente. Seu espírito aparece no túmulo depois que o Cavaleiro obtém o Dream Nail.', 'https://cdn.wikimg.net/en/hkwiki/images/6/6c/B_Gorb.png'),
('Cornifer', 'Forgotten Crossroads', 'NPC', 'O cartógrafo viajante, cantarolando enquanto desenha as primeiras passagens de Hallownest. Vende o mapa local.', 'https://cdn.wikimg.net/en/hkwiki/images/f/ff/Cornifer.png'),
('Charm Lover Salubra', 'Forgotten Crossroads', 'NPC', 'Lesma comerciante que vende Charms e Charm Notches em uma loja acima da vila abandonada. Parece ignorar o colapso do reino.', 'https://cdn.wikimg.net/en/hkwiki/images/e/ea/Salubra.png'),
('Grubfather', 'Forgotten Crossroads', 'NPC', 'O velho patriarca da colônia de Grubs. Seus filhos foram presos em jarros pelo Collector; ao libertá-los, o Cavaleiro é recompensado.', 'https://cdn.wikimg.net/en/hkwiki/images/b/be/Grubfather.png'),
('Snail Shaman', 'Forgotten Crossroads', 'NPC', 'Habita o Ancestral Mound e ensina o feitiço Vengeful Spirit ao Cavaleiro. Está preso ali e não consegue visitar sua tribo.', 'https://cdn.wikimg.net/en/hkwiki/images/3/38/Snail_Shaman.png'),
('Myla', 'Forgotten Crossroads', 'NPC', 'Mineira alegre que canta enquanto procura tesouros nos cristais, no nordeste da região. Com o tempo, a Infecção a transforma em um Husk Miner.', 'https://cdn.wikimg.net/en/hkwiki/images/b/b0/Myla.png'),
('Tiso', 'Forgotten Crossroads', 'NPC', 'Aventureiro arrogante, encontrado em um banco da Estação do Stag das Encruzilhadas.', 'https://cdn.wikimg.net/en/hkwiki/images/b/b1/Tiso.png'),
('Quirrel', 'Greenpath', 'NPC', 'Viajante amigável e curioso, de máscara misteriosa e espada em forma de cutelo. Aparece no templo de Unn, contemplando as belezas e os perigos de Greenpath.', 'https://cdn.wikimg.net/en/hkwiki/images/c/cd/Quirrel_Idle.png'),
('The Hunter', 'Greenpath', 'NPC', 'Vive numa pequena caverna no sudeste, acima do Stone Sanctuary, e entrega ao Cavaleiro o Diário do Caçador para registrar as criaturas de Hallownest.', 'https://cdn.wikimg.net/en/hkwiki/images/4/4b/Hunter.png'),
('Cornifer', 'Greenpath', 'NPC', 'O cartógrafo que desenha e vende os mapas detalhados das cavernas de Greenpath.', 'https://cdn.wikimg.net/en/hkwiki/images/f/ff/Cornifer.png'),
('Zote the Mighty', 'Greenpath', 'NPC', 'Guerreiro autoproclamado, preso pelo Vengefly King na parte norte da região. O Cavaleiro pode escolher salvá-lo ou deixá-lo.', 'https://cdn.wikimg.net/en/hkwiki/images/5/5a/B_Zote.png'),
('Nailmaster Sheo', 'Greenpath', 'NPC', 'Mestre de Nail Arts, vive isolado na sua cabana do sudoeste e ensina a Great Slash. Se o Nailsmith for poupado, ele se muda para lá.', 'https://cdn.wikimg.net/en/hkwiki/images/7/75/Nailmaster_Sheo.png'),
('Unn', 'Greenpath', 'NPC', 'A Ser Superior que os Mosskin veneram. Fica no fundo do Lago de Unn, a oeste, e é considerada criadora da flora local.', 'https://cdn.wikimg.net/en/hkwiki/images/b/ba/Unn.png'),
('No Eyes', 'Greenpath', 'Espírito', 'Espírito melancólico e sem olhos que repousa no Stone Sanctuary, no fim de uma passagem escura abaixo do banco.', 'https://cdn.wikimg.net/en/hkwiki/images/3/3b/B_No_Eyes.png'),
('Monomon the Teacher', 'Fog Canyon', 'NPC', 'Uma das Três Sonhadoras. Dorme no Arquivo da Professora, protegida por Uumuu, depois de ter buscado deter a Infecção.', 'https://cdn.wikimg.net/en/hkwiki/images/1/14/Monomon.png'),
('Quirrel', 'Fog Canyon', 'NPC', 'Aparece pela primeira vez do lado de fora do Arquivo da Professora e fala sobre o que há lá dentro.', 'https://cdn.wikimg.net/en/hkwiki/images/c/cd/Quirrel_Idle.png'),
('Millibelle the Banker', 'Fog Canyon', 'NPC', 'Montou um banco nos arredores do cânion, perto da Queen''s Station, onde guarda o Geo de quem deposita.', 'https://cdn.wikimg.net/en/hkwiki/images/2/24/Millibelle.png'),
('Cornifer', 'Fog Canyon', 'NPC', 'Tentando cartografar as passagens flutuantes e ácidas do cânion.', 'https://cdn.wikimg.net/en/hkwiki/images/f/ff/Cornifer.png'),
('Quirrel', 'Fungal Wastes', 'NPC', 'Aparece duas vezes: no centro da Queen''s Station e perto da Vila Mantis. Fala sobre a Tribo Mantis e a Infecção.', 'https://cdn.wikimg.net/en/hkwiki/images/c/cd/Quirrel_Idle.png'),
('Leg Eater', 'Fungal Wastes', 'NPC', 'Lojista do nordeste dos Ermos Fúngicos. Vende Fragile Charms.', 'https://cdn.wikimg.net/en/hkwiki/images/4/4a/Leg_Eater.png'),
('Cloth', 'Fungal Wastes', 'NPC', 'Viajante que se esconde sob o solo perto da loja de Leg Eater e avisa sobre uma tribo de guerreiros mais adiante.', 'https://cdn.wikimg.net/en/hkwiki/images/5/51/Cloth.png'),
('Willoh', 'Fungal Wastes', 'NPC', 'Mora na sala acima da Queen''s Station, comendo um fungo raro que descobriu.', 'https://cdn.wikimg.net/en/hkwiki/images/4/43/Willoh.png'),
('Bretta', 'Fungal Wastes', 'NPC', 'Está presa no extremo sul, perto da Vila Mantis. Pode ser libertada e voltar a Dirtmouth.', 'https://cdn.wikimg.net/en/hkwiki/images/9/96/Bretta.png'),
('Mister Mushroom', 'Fungal Wastes', 'NPC', 'Arauto que visita sete regiões; os Ermos Fúngicos são sua primeira parada.', 'https://cdn.wikimg.net/en/hkwiki/images/f/fc/Mister_Mushroom.png'),
('Elder Hu', 'Fungal Wastes', 'Espírito', 'Espírito de um Ancião guerreiro, no nordeste, perto da entrada da Cidade das Lágrimas.', 'https://cdn.wikimg.net/en/hkwiki/images/e/ed/B_Elder_Hu.png'),
('White Lady', 'Queen''s Gardens', 'NPC', 'A ex-regente de Hallownest, confinada em sua câmara nos jardins. Entrega o White Fragment depois que o Traitor Lord é derrotado.', 'https://cdn.wikimg.net/en/hkwiki/images/9/97/White_Lady_Full.png'),
('Moss Prophet', 'Queen''s Gardens', 'NPC', 'Prega na Moss Chapel, acompanhado dos Mossy Vagabonds, e lidera os seguidores do musgo que vivem ali.', 'https://cdn.wikimg.net/en/hkwiki/images/8/8b/Moss_Prophet.png'),
('The Last Stag', 'Queen''s Gardens', 'NPC', 'Preso à Estação do Stag nos jardins. Lembra que a estação foi um retiro da antiga Rainha, pouco usado pelo povo comum.', 'https://cdn.wikimg.net/en/hkwiki/images/a/af/Last_Stag.png'),
('Cloth', 'Queen''s Gardens', 'NPC', 'Se o Cavaleiro conversou com ela na Bacia Antiga, ela aparece para ajudar na arena do Traitor Lord.', 'https://cdn.wikimg.net/en/hkwiki/images/5/51/Cloth.png'),
('Cornifer', 'Queen''s Gardens', 'NPC', 'Relaxando entre as plantas ornamentais e flores exóticas dos jardins.', 'https://cdn.wikimg.net/en/hkwiki/images/f/ff/Cornifer.png'),
('Midwife', 'Deepnest', 'NPC', 'Misteriosa criatura aracnídea que mora nos túneis escuros e conversa com os viajantes pelas frestas.', 'https://cdn.wikimg.net/en/hkwiki/images/e/ed/Midwife.png'),
('Zote the Mighty', 'Deepnest', 'NPC', 'Em Deepnest, o Cavaleiro tem uma segunda chance de salvá-lo; diferente de Greenpath, ele não pode morrer aqui.', 'https://cdn.wikimg.net/en/hkwiki/images/5/5a/B_Zote.png'),
('Brumm', 'Deepnest', 'NPC', 'Aparece em Distant Village depois que Grimm é derrotado.', 'https://cdn.wikimg.net/en/hkwiki/images/5/5f/Brumm.png'),
('Cloth', 'Deepnest', 'NPC', 'Encontrada perto do Failed Tramway Bench se ainda não tiver sido resgatada na Bacia Antiga.', 'https://cdn.wikimg.net/en/hkwiki/images/5/51/Cloth.png'),
('Cornifer', 'Deepnest', 'NPC', 'O cartógrafo viajante, que mapeia os túneis cobertos de teia.', 'https://cdn.wikimg.net/en/hkwiki/images/f/ff/Cornifer.png'),
('Mister Mushroom', 'Deepnest', 'NPC', 'Arauto que visita sete regiões; Deepnest é uma de suas paradas.', 'https://cdn.wikimg.net/en/hkwiki/images/f/fc/Mister_Mushroom.png'),
('Hornet', 'Deepnest', 'NPC', 'Aparece ao lado de Herrah, sua mãe, depois que ela é derrotada, se Hornet já foi enfrentada em Kingdom''s Edge.', 'https://cdn.wikimg.net/en/hkwiki/images/8/89/B_Hornet.png'),
('Herrah the Beast', 'Deepnest', 'Espírito', 'Uma das Três Sonhadoras e rainha das aranhas, adormecida em seu casulo na Beast''s Den.', 'https://cdn.wikimg.net/en/hkwiki/images/b/bc/Herrah.png'),
('Cloth', 'Ancient Basin', 'NPC', 'Viajante resgatada na Bacia Antiga; depois pode ajudar o Cavaleiro em batalhas na região dos Jardins da Rainha.', 'https://cdn.wikimg.net/en/hkwiki/images/5/51/Cloth.png'),
('Mister Mushroom', 'Ancient Basin', 'NPC', 'Arauto que visita sete regiões de Hallownest; a Bacia Antiga é uma de suas paradas.', 'https://cdn.wikimg.net/en/hkwiki/images/f/fc/Mister_Mushroom.png'),
('Cornifer', 'Ancient Basin', 'NPC', 'O cartógrafo viajante, desenhando o terreno cinzento e perigoso da Bacia Antiga.', 'https://cdn.wikimg.net/en/hkwiki/images/f/ff/Cornifer.png'),
('Relic Seeker Lemm', 'City of Tears', 'NPC', 'O antiquário de Hallownest, que examina e compra relíquias. Sua loja fica no lado oeste da cidade.', 'https://cdn.wikimg.net/en/hkwiki/images/b/be/Relic_Seeker_Lemm.png'),
('Nailsmith', 'City of Tears', 'NPC', 'Vive numa cabana isolada, no oeste da cidade, aperfeiçoando o Nail do Cavaleiro em troca de Geo e Pale Ore.', 'https://cdn.wikimg.net/en/hkwiki/images/f/f6/Nailsmith_2.png'),
('Hornet', 'City of Tears', 'NPC', 'Encontrada na Fountain Square, diante do memorial ao Hollow Knight.', 'https://cdn.wikimg.net/en/hkwiki/images/8/89/B_Hornet.png'),
('Quirrel', 'City of Tears', 'NPC', 'Viajante que aparece em diferentes pontos da cidade, no lado oeste.', 'https://cdn.wikimg.net/en/hkwiki/images/c/cd/Quirrel_Idle.png'),
('Zote the Mighty', 'City of Tears', 'NPC', 'Guerreiro autoproclamado, encontrado no lado oeste da cidade sob certas condições.', 'https://cdn.wikimg.net/en/hkwiki/images/5/5a/B_Zote.png'),
('Poggy Thorax', 'City of Tears', 'NPC', 'Fica no fundo da cozinha da Pleasure House, no 5º andar, e comenta o tamanho do Cavaleiro.', 'https://cdn.wikimg.net/en/hkwiki/images/0/02/Poggy-Thorax.png'),
('Eternal Emilitia', 'City of Tears', 'NPC', 'Antigo membro da alta casta, expulso pelos antigos pares. Vive feliz num quarto escondido que liga a cidade às Vias Fluviais.', 'https://cdn.wikimg.net/en/hkwiki/images/d/d7/Eternal_Emilitia.png'),
('Millibelle', 'City of Tears', 'NPC', 'Pode ser encontrada num banco perto da fonte termal da Pleasure House depois de fugir com o Geo depositado.', 'https://cdn.wikimg.net/en/hkwiki/images/2/24/Millibelle.png'),
('Songstress Marissa', 'City of Tears', 'Espírito', 'Espírito de uma antiga artista, que ainda canta no palco do teatro abandonado da Pleasure House.', 'https://cdn.wikimg.net/en/hkwiki/images/d/d5/Marissa.png'),
('Lurien the Watcher', 'City of Tears', 'Espírito', 'Um dos Três Sonhadores, que observa a cidade do alto de sua torre, a Watcher''s Spire.', 'https://cdn.wikimg.net/en/hkwiki/images/7/77/Lurien.png'),
('Tuk', 'Royal Waterways', 'NPC', 'Encontrado no lado oeste das Vias Fluviais.', 'https://cdn.wikimg.net/en/hkwiki/images/a/a1/Tuk.png'),
('Fluke Hermit', 'Royal Waterways', 'NPC', 'Eremita no lado oeste, perto do Junk Pit. Afirma que a pilha de lixo é o tesouro de Flukemarm.', 'https://cdn.wikimg.net/en/hkwiki/images/0/06/Fluke_Hermit.png'),
('Godseeker', 'Royal Waterways', 'NPC', 'Hiberna num sarcófago dourado no Junk Pit, que só se abre com uma Simple Key.', 'https://cdn.wikimg.net/en/hkwiki/images/d/d2/Godseeker.png'),
('Dung Defender', 'Royal Waterways', 'NPC', 'Nobre cavaleiro das vias fluviais, que defende os esgotos com bolas de esterco e se despede gritando "DOMA DOMA DOMA"!', 'https://cdn.wikimg.net/en/hkwiki/images/0/0e/B_Dung_Defender.png'),
('Cornifer', 'Royal Waterways', 'NPC', 'Tentando mapear os túneis inundados sem se sujar demais.', 'https://cdn.wikimg.net/en/hkwiki/images/f/ff/Cornifer.png'),
('Myla', 'Crystal Peak', 'NPC', 'Mineira absorta em seu trabalho, cantando enquanto coleta cristais. Se a Infecção a tomar, vira um Husk Miner.', 'https://cdn.wikimg.net/en/hkwiki/images/b/b0/Myla.png'),
('Cornifer', 'Crystal Peak', 'NPC', 'Cantarolando alegremente enquanto mapeia as cavernas brilhantes de cristais.', 'https://cdn.wikimg.net/en/hkwiki/images/f/ff/Cornifer.png'),
('Snail Shaman (tia)', 'Crystal Peak', 'NPC', 'A quarta tia de um Snail Shaman, presa em cristal no Crystallised Mound. Libertá-la concede o feitiço Descending Dark.', 'https://cdn.wikimg.net/en/hkwiki/images/3/38/Snail_Shaman.png'),
('Seer', 'Resting Grounds', 'NPC', 'Última sobrevivente da Tribo Moth. Entrega o Dream Nail ao Cavaleiro e o recompensa conforme ele coleta Essence.', 'https://cdn.wikimg.net/en/hkwiki/images/e/ee/Seer.png'),
('Grey Mourner', 'Resting Grounds', 'NPC', 'Antiga Grande Cavaleira que chora o amor de uma Mantis. Pede ao Cavaleiro que leve uma Delicate Flower ao túmulo do amado.', 'https://cdn.wikimg.net/en/hkwiki/images/3/3d/Grey_Mourner.png'),
('Cornifer', 'Resting Grounds', 'NPC', 'Mapeando as catacumbas sagradas repletas de túmulos ancestrais.', 'https://cdn.wikimg.net/en/hkwiki/images/f/ff/Cornifer.png'),
('Xero', 'Resting Grounds', 'Espírito', 'Espírito de um antigo guerreiro de Hallownest, cujas lâminas flutuantes testam os vivos.', 'https://cdn.wikimg.net/en/hkwiki/images/e/ed/B_Xero.png'),
('Bardoon', 'Kingdom''s Edge', 'NPC', 'Uma lagarta gigantesca que subiu até o alto para escapar da Infecção. Conta o que sabe sobre as origens do Rei Pálido e insiste que não é um Wyrm.', 'https://cdn.wikimg.net/en/hkwiki/images/2/24/Bardoon.png'),
('Nailmaster Oro', 'Kingdom''s Edge', 'NPC', 'Recluso discípulo do Grande Nailsage Sly e irmão de Mato e Sheo. Vive em uma cabana isolada e ensina o Dash Slash.', 'https://cdn.wikimg.net/en/hkwiki/images/4/4e/Oro.png'),
